-- 2257 🏋️ Exercises from the book "coaching-3-5-2-tactics-125-tactical-solutions-and-practices" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'coaching-3-5-2-tactics-125-tactical-solutions-and-practices');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Back three and DM build-up passing warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 106, 108, 'Training Session 1: Practice 1 (Unopposed Build-up Play Passing Warm-up)', 'Renato Montagnolo', 'Rehearse the 3 centre backs circulating the ball and using the defensive midfielder to build up from the back in a 3-5-2.', 'Middle area of the pitch; a trio of centre backs at each end (blue and red) with one defensive midfielder in the centre circle between them. Wing backs can be added.', 'Blue back three move the ball with max 2 touches, then one wide centre back carries forward and plays to a centre back of the far trio. That receiver hits the DM first time (quick transition to attack), the DM sets it back to a different player of that trio and the pattern restarts from that end.', 'Centre backs max 2 touches while circulating; receiving centre back plays a one-touch pass into the DM.', 'Variation 1: wide centre back dribbles forward before passing to the far trio. Variation 2: centre back plays into the DM, who lays it off for a different centre back running forward, who then plays to the far trio. Variation 3: wide centre back switches with a diagonal lofted pass to the far wide centre back.', 'Wide centre backs stay spread; carry into space; crisp first-time pass into the DM; DM sets to a different player each time.', '7 (2 x 3 centre backs + 1 DM), wing backs optional', 7, 9, 'middle third of the pitch', NULL, NULL, NULL, false, false, true, NULL, 10),
  ('Build-up 8+GK v 6 through pole gates', 'phase_of_play', 'opposed', 'in_possession', 109, 109, 'Session 1: Practice 2', NULL, 'Build out from the back in a 3-5-2 against an aggressive, outnumbered press.', 'Half a pitch with a big goal and GK; blue 8 outfield in 3-5-2 shape v 6 reds in a 4-2 (adjustable); 2 pole gates near halfway.', 'GK plays short to one of the 3 centre backs and blues use the extra men to beat the red press, scoring by dribbling over halfway or passing through a gate. Reds press hard and on winning it counter quickly at the big goal.', 'Before a goal counts blues need 7 passes or a touch from all 3 central midfielders.', NULL, 'Reds press aggressively and together; blues exploit the numerical advantage.', '8 (+GK) v 6', 15, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Four-zone build-up through the lines', 'phase_of_play', 'overload', 'in_possession', 110, 110, 'Session 1: Practice 3', NULL, 'Progress the ball zone by zone from the GK to a forward or midfielder running beyond the midfield line.', '4 horizontal zones across the pitch plus wide channels where only 2 neutral wing backs play. Zone 1 4v3 (GK + 3 CBs v 3), Zone 2 3 midfielders v 3, Zone 3 2 red interceptors, Zone 4 forwards and GK.', 'GK starts; CBs use the neutral wing backs to find a midfielder in Zone 2 (a free CB may dribble in for 4v3). Midfielders then pass into Zone 4 for a forward dropping or a central midfielder running forward, who must score past the GK.', 'A neutral wing back must touch the ball during the build-up. Zone 3 reds only intercept and stay in their zone. Receiver beyond Zone 4 must score within 5 seconds. If reds win it, roles switch and play restarts from the GK.', NULL, NULL, 'Two teams in 3-5-2 shape + 2 neutral wing backs + GKs', NULL, NULL, 'Full pitch, 4 zones', NULL, NULL, NULL, true, true, true, NULL, 30),
  ('Beat the press, play behind midfield line', 'phase_of_play', 'overload', 'in_possession', 111, 111, 'Session 1: Practice 4', NULL, 'Build up against an ultra-aggressive press and find a team-mate behind the opposition midfield line.', 'Full pitch split into 4 zones. Zone 1: GK + 4 blues v 3 red attackers; Zone 2 blue DM; Zone 3: 4 red midfielders who only intercept with blue F and RCM beyond; Zone 4 one red defender and GK.', 'GK plays short and blues use the 5v3 to pass into Zone 3 (e.g. LCB long to F). The receiver then attacks 2v1 against the last red defender to score.', 'Zone 3 reds can only intercept; an interception launches a 4v4 counter (interceptor + 3 attackers). If reds win it in Zone 1 they try to score quickly.', NULL, 'Useful against opponents who press very high and aggressively.', '5v3 in Zone 1 (incl. GK), 2v1 up front', NULL, NULL, 'Full pitch, 4 zones', NULL, NULL, NULL, true, true, true, NULL, 40),
  ('3v3 receiving zones to six mini goals', 'small_sided_game', 'opposed', 'in_possession', 113, 114, 'Session 2: Practice 1', NULL, 'Time forward runs to receive in behind a line and finish quickly.', '20 x 30 yard area with a 3 yard receiving zone at each end and 3 mini goals beyond each end; coach on the side with balls.', 'Coach feeds either team for 3v3. The team in possession has free touches and tries to play a team-mate into the receiving zone, who then shoots at a mini goal.', 'Defenders may only intercept, no tackling. A goal needs: scored within 10 seconds of the coach''s pass; max 2 touches in the receiving zone (receive and shoot); receiver must run into the zone after the pass, not wait there.', 'Variation 3v3 (+2): add 2 jokers in wide positions as wing backs who play for the team in possession but cannot receive in the receiving zones or score; coach restarts with a new ball to the other team after each goal or ball out.', NULL, '3v3 (+2 jokers in variation)', 6, 8, '20 x 30 yards', 27.4, 18.3, NULL, true, false, true, NULL, 50),
  ('8v8 through the lines to six mini goals', 'small_sided_game', 'opposed', 'in_possession', 115, 115, 'Session 2: Practice 2', NULL, 'Build up through pressure and get a central midfielder running in behind to receive and score.', 'Full pitch: main area plus 2 receiving zones (yellow) at each end, 3 mini goals beyond each zone; coach starts play from the side.', 'Coach passes to a centre back and teams play 8v8 in 3-5-2 shapes. Blues build up and play in behind for LCM or RCM to arrive in the receiving zone and finish in a mini goal.', 'Possession team unlimited touches; defenders only intercept. Max 2 touches in the receiving zone; receiver must arrive after the pass with a forward run.', NULL, NULL, '8v8', 16, 16, 'Full pitch', NULL, NULL, NULL, true, false, true, NULL, 60),
  ('3-5-2 midfield-line pattern of play', 'passing_unopposed', 'unopposed', 'in_possession', 116, 117, 'Session 2: Practice 3', NULL, 'Rehearse 3-5-2 build-up patterns that get the ball between and beyond the opposition midfield line.', 'Full pitch, 2 teams in 3-5-2 shape on opposite halves; a line of mannequins in midfield represents the opponent midfield; coaches with balls on the sides.', 'Coach feeds a CB or WB and the back line circulates. When a CB dribbles out or a WB receives, the near central midfielder chooses to drop short or run beyond the mannequins; WB passes to him or to the DM, and the DM finds the other CM between the lines. The CM receives facing forward and passes to a red CB, and reds repeat the other way.', NULL, 'Variation - CM drops back: LCM drops to take a short pass from the LWB and plays the DM (who stays central), while RCM chooses a short unmarking move or a run behind the mannequins to take the DM''s forward pass.', 'Receive with an open body shape facing forward.', '2 teams of 10 outfield (3-5-2)', NULL, NULL, 'Full pitch', NULL, NULL, NULL, false, false, true, NULL, 70),
  ('Central overload then finish in behind', 'phase_of_play', 'overload', 'in_possession', 118, 118, 'Session 2: Practice 4', NULL, 'Use a central overload to find a midfielder in the receiving zone and then attack the goal.', 'Full pitch with a central zone (white) and 2 receiving zones (yellow); 11 blues v only 2 red central midfielders and a GK active (11v3); yellow joker DM in the middle.', 'GK plays short, blues build up unopposed, then pass into the centre where it is 3v2 with the DM joker. A CM receives in the receiving zone, plays in behind the defensive line and 4-6 blues attack unopposed to score.', 'Max 2 touches in the receiving zone; receiver must arrive with a forward run after the pass.', NULL, NULL, '11v3 (2 red CMs + GK)', 14, 14, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 80),
  ('11v11 through the lines with zone overloads', 'conditioned_game', 'overload', 'in_possession', 119, 119, 'Session 2: Practice 5', NULL, 'Build through the thirds using overloads in each zone and finish quickly in the end zone.', 'Full pitch with a central zone and 2 receiving zones: low zone 3 (+GK) v 2, central zone 6v5 (one CB steps up), final zone 4v3.', 'GK plays to a CB who uses the 4v2 to reach the central area, where a CB dribbles in to make 6v5. Blues then pass to a player in the receiving zone and 2 players join to attack 4v3 and score.', '2 red forwards who win it must score in 5 seconds; 5 red midfielders who win it must score in 8-10 seconds; 3 red CBs win it and complete 2 passes for a point. Max 2 touches in the receiving zone. Teams switch roles after each phase and the other GK restarts.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 90),
  ('Three-colour switch-of-play warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 121, 121, 'Session 3: Practice 1', NULL, 'Pass and move in tight spaces and switch play quickly to the weak side.', '10 outfield players in 3 bib colours (red, blue, yellow) in 3-5-2 positions plus 1 GK; cones scattered as obstacles and mannequins in front of the box.', 'One of the 3 deepest players starts and the ball is circulated, passing only to a different colour. When the ball is wide the coach whistles and players must switch to the weak side and score.', 'Max 2 touches. After the whistle: switch to the weak side, if coach whistles with red on the ball it must go to a yellow and vice versa, and score within 10 seconds.', NULL, NULL, '10 outfield + 1 GK', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Three-zone 8v8 (+2) switching possession', 'possession', 'overload', 'in_possession', 122, 122, 'Session 3: Practice 2', NULL, 'Move the ball from one wide zone to the other in a 3-5-2 shape.', 'Central zone plus 2 wide no-contest zones; each team has LCB, RCB, LWB, RWB, LCM, RCM, F1, F2; 2 yellow jokers play CB and DM for the team in possession. Wing backs stay in the wide zones.', 'Coach passes to the joker CB and the team in possession tries to move the ball from one wing back to the other.', 'Always start from the coach to the joker CB. Unlimited touches. Wing backs do not contest each other. 1 point every time the ball goes from one wide side to the other.', NULL, NULL, '8v8 (+2)', 18, 18, NULL, NULL, NULL, NULL, false, false, false, NULL, 110),
  ('Three-zone switch game to four mini goals', 'small_sided_game', 'overload', 'in_possession', 123, 123, 'Session 3: Practice 3', NULL, 'Switch play from one wide zone to the other and then finish.', 'Same 3-zone area as the 8v8 (+2) game with 4 mini goals added, one at each corner of the wide zones.', 'Coach feeds the joker CB; teams play with wing backs in the wide zones and others central, trying to switch the play and score in a mini goal.', 'Start from the coach to the joker CB; unlimited touches; score on either side; wing backs may now contest each other; a goal after a switch from one wide zone to the other counts double.', NULL, NULL, '8v8 (+2)', 18, 18, NULL, NULL, NULL, NULL, true, false, true, NULL, 120),
  ('Three-zone 11v11 switching play game', 'conditioned_game', 'opposed', 'in_possession', 124, 125, 'Session 3: Practice 4', NULL, 'Switch play in a full-team game and create overloads in the wide zones.', 'Larger area with 2 big goals and GKs, 3 vertical zones (2 wide, 1 central). Can also be played with fewer players.', 'Start from the GK and play a conditioned 11v11 focused on switching the play.', 'Unlimited touches. If 1 blue enters a wide zone no red may enter (2v1); if 2 blues enter, 1 red may (3v2). A goal after the ball goes from one wide zone to the other counts double.', 'Variation - fast unopposed attack: after a successful switch, all opponents except the 3 centre backs become passive and the attackers have 6 seconds to score; then restart from the other GK.', NULL, '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Final pass and timed runs behind line', 'combination', 'unopposed', 'in_possession', 127, 128, 'Session 4: Practice 1', NULL, 'Combine through midfield, play the final pass and time forwards'' runs in behind the back line.', '4-5 mannequins as the opposition back line, lots of cones as obstacles; 3 blue midfielders and 2 yellow forwards; GK in goal; coach with balls.', 'Coach plays to the DM and players circulate, always passing to a different colour (midfielder to forward and back via lay-off). On the whistle a midfielder plays the final pass in behind; both forwards time runs, the receiver shoots and the other follows for rebounds.', 'Each pass must go to a different colour bib.', 'Progression - full 10 outfield players in 3-5-2, same colour: coach passes to a CB and the team circulates alternating 1 touch and 2 touches; on the whistle the player in possession plays in behind for the forwards, while the far side players support for rebounds.', NULL, '5 players (or full 10 outfield) + GK', 6, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 140),
  ('7v7 (+3) possession then pass in behind', 'phase_of_play', 'overload', 'in_possession', 129, 129, 'Session 4: Practice 2', NULL, 'Keep the ball, then after a lay-off play in behind and finish.', 'Marked area in front of a goal with GK; 2 teams of 7 plus 3 jokers; coach with balls; end zone beyond the defending line.', 'Coach feeds and the team keeps the ball. After 6 passes they play a lay-off and a pass in behind for a runner to score.', 'Unlimited touches. 6 passes before the final ball (adjust for age/level). After 6 passes defenders can only intercept, no tackling. Defenders stay in the main area. Receiver enters the end zone only after the pass (offside) and first touch must be forward.', NULL, NULL, '7v7 (+3)', 18, 18, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('10v10 game with receiving end zones', 'positional_game', 'opposed', 'in_possession', 130, 130, 'Session 4: Practice 3', NULL, 'Build up through pressure and play a final ball for a runner to receive in the end zone.', 'Main area plus 2 receiving end zones (yellow); 10v10 in 3-5-2 shapes; coach starts play.', 'Coach passes to a centre back and teams play 10v10. After 6 passes the team plays a final pass for a player to receive in the end zone, which counts as a goal.', 'Unlimited touches; 6 passes before the final ball (adjust); after 6 passes defenders only intercept; final pass 1 touch, ground or air; defenders cannot enter end zones; receiver enters only after the pass; first touch must be forward.', NULL, NULL, '10v10', 20, 20, NULL, NULL, NULL, NULL, false, false, true, NULL, 160),
  ('11v11 play in behind with end zones', 'conditioned_game', 'opposed', 'in_possession', 131, 131, 'Session 4: Practice 4', NULL, 'Play through pressure and release a runner in behind to score.', 'Full pitch, outfield players all inside a marked middle zone, end zones and big goals with GKs at each end.', 'GK plays to a centre back; team builds up and plays a final pass in behind for a player to receive in the end zone and score.', 'Final pass in behind only straight after a sideways or back pass, and with 1 touch (ground or air). Unlimited touches otherwise. Defenders cannot enter end zones; receiver enters after the pass; 4 seconds to score unopposed after receiving in the end zone.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Two-forward combined movements passing warm-up', 'combination', 'unopposed', 'in_possession', 133, 133, 'Session 5: Practice 1', NULL, 'Teach the forwards'' combined movements (dummy, drop and spin) without opponents.', '6 players (LWB, LCM, DM, RWB, F1, F2) with a GK in goal; coach with balls; can be done with all 11.', 'Coach starts and players circulate. On the whistle the player in possession passes to the nearest forward; the coach calls ''Time'' or ''Man-on''. On ''Man-on'' F1 dummies to F2, drops to drag his marker and spins forward to receive in behind and score.', NULL, 'Patterns can be varied using the book''s analysis of forwards'' combined movements (pp. 21-28).', 'Forward reacts to the coach''s call about pressure.', '6 (or 11) + GK', 7, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Three-zone build-up, two-forward combination', 'phase_of_play', 'overload', 'in_possession', 134, 135, 'Session 5: Practice 2', NULL, 'Build up and use the two forwards'' combined movement to break in behind.', '3/4 of a pitch in 3 zones: Zone 1 6v4, Zone 2 4v3 (red defenders cannot leave), Zone 3 GK.', 'Blues complete 4-6 passes in Zone 1, then one player dribbles into Zone 2 for a 5v3. A forward drags his marker away and a midfielder plays a diagonal into the space for the other forward to score.', 'All reds stay in their zones. Restart from Zone 1 with a blue defender.', 'Progression - defenders can defend deep: Zones 2 and 3 merged so the 3 red CBs can drop and defend freely.', NULL, '6v4 + 4v3 + GK', 18, 18, '3/4 pitch', NULL, NULL, NULL, true, true, true, NULL, 190),
  ('11v11 forward combinations with finishing zones', 'conditioned_game', 'opposed', 'in_possession', 136, 136, 'Session 5: Practice 3', NULL, 'Reward the two forwards'' combined movements in a full game.', 'Full pitch, outfield players in a marked middle zone, finishing zones and goals with GKs at each end.', 'GK plays to a CB; team builds up and plays a final pass for a player to receive in behind and score.', 'Only the player receiving in behind can leave the middle zone. A goal from a forwards'' combined movement counts double.', NULL, NULL, '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 200),
  ('7v3 counter-press with four mini goals', 'transition', 'overload', 'to_defend', 138, 138, 'Session 6: Practice 1', NULL, 'React instantly to losing the ball by pressing the new ball carrier.', '20 x 25 yards with 4 mini goals, one per side; 7 blues v 3 reds; coach with balls.', 'Coach starts; blues keep possession. When they lose it they press immediately to win it back.', 'Blues score 1 point for 15 passes and 1 point for winning the ball back before the new carrier passes. Reds score by 4 passes or by scoring in a mini goal after at least 1 pass.', NULL, 'Small area keeps the mini goals close so the reaction must be fast.', '7v3', 10, 10, '20 x 25 yards', 22.9, 18.3, NULL, true, false, false, NULL, 210),
  ('10v5 counter-press with six mini goals', 'transition', 'overload', 'to_defend', 139, 139, 'Session 6: Practice 2', NULL, 'Counter-press after losing the ball within a 3-5-2 shape.', 'Larger area with 6 mini goals around it; 10 blues in 3-5-2 v 5 reds; coach with balls.', 'Blues keep possession with constant movement; on losing it they press immediately to recover it.', 'Blues 1 point for 15 passes and 1 for winning it back before the new carrier passes. Reds 1 point for 4 passes or a mini goal after at least 1 pass.', NULL, 'Keep moving to change angles and give the ball carrier options.', '10v5', 15, 15, NULL, NULL, NULL, NULL, true, false, false, NULL, 220),
  ('Dynamic 10v8 (+GK) fast defensive transition', 'transition', 'overload', 'to_defend', 140, 140, 'Session 6: Practice 3', NULL, 'Win the ball back fast while keeping defensive balance and shape.', 'Half a pitch; blue 10 outfield in 3-5-2 attacking a goal with GK defended by 8 reds in a 3-5 shape.', 'Coach passes to a blue defender; blues build up to score past the GK. When they lose it they press immediately.', 'Reds score 1 point by dribbling over halfway or completing 7 passes.', NULL, 'Stay balanced and compact so reds cannot break through.', '10v8 (+GK)', 19, 19, 'Half pitch', NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Three-zone game, stop the back pass', 'transition', 'opposed', 'to_defend', 141, 141, 'Session 6: Practice 4', NULL, 'Press immediately after losing the ball to stop the opponent playing back to their GK.', '2/3 of a pitch in 3 zones; full 11v11 including GKs.', 'Blue GK starts and blues play in Zones 1-2, aiming for 7 passes then playing into Zone 3 to score. If reds win it they look to play back to their GK; blues press to win it back and block the back pass.', 'Reds only intercept and none may defend in Zone 3. Reds score 1 point with a back pass to their GK; blues 1 point for winning it back, restart from the blue GK.', NULL, NULL, '11v11', 22, 22, '2/3 pitch', NULL, NULL, NULL, true, true, true, NULL, 240),
  ('11v11 whistle new ball transition game', 'conditioned_game', 'opposed', 'to_defend', 142, 142, 'Session 6: Practice 5', NULL, 'Rehearse the attack-to-defence transition inside a real 11v11 game.', 'Full pitch 11v11 with GKs; coach on the touchline with balls.', 'Normal game; at any moment the coach whistles and plays a new ball to the team out of possession. They try to keep it for 10 seconds while the other team transitions fast to win it back.', 'Reds 1 point for 10 seconds possession; blues 1 point for winning it within 10 seconds, then reds go passive and blues can score unopposed for an extra point.', NULL, 'Nearest players press the ball and block receivers; the rest stay compact and recover position.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('7v7 pressing game with GK end zones', 'positional_game', 'opposed', 'out_of_possession', 144, 144, 'Session 7: Practice 1', NULL, 'Make the defending team press intensively and continuously.', 'Main zone with 2 teams of 7 and a GK in each end zone; adjust size for age/level.', 'Coach starts; the team in possession scores by passing to its GK or completing 6 consecutive passes. After a point the same team restarts from the opposing GK.', '2 ways to score so defenders cannot just block the path to the GK.', NULL, 'Play in short bouts (e.g. 3 minutes) to keep intensity high.', '7v7 + 2 GKs', 16, 16, NULL, NULL, NULL, NULL, false, true, true, NULL, 260),
  ('High press v build-up to four mini goals', 'defending', 'opposed', 'out_of_possession', 145, 145, 'Session 7: Practice 2', NULL, 'Press high to stop the opponent building up and counter quickly.', 'Both teams 3-5-2; reds defend a big goal with GK and attack 4 mini goals 10 yards past halfway.', 'Red GK plays short to a defender; reds build up to score in a mini goal, keeping the ball on the ground. Blues start passive (reds 2 touches); on the coach''s whistle they press fully, win the ball and counter on the big goal.', 'Counter can be against passive or active opponents; limit total passes or seconds to score.', NULL, 'Risk of teaching blind forward pressing; alternate with practices where opponents can go long in behind.', '11v11 (3-5-2 both)', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('Aggressive pressing after losing the ball', 'transition', 'opposed', 'to_defend', 146, 146, 'Session 7: Practice 3', NULL, 'Apply aggressive pressing in the transition from attack to defence.', 'Same area as the high-press game: big goal with GK, 4 mini goals; reds in any formation.', 'Blue middle CB starts with the coach in midfield; blues build up to score in the big goal. At the end of a phase or any time the coach plays a new ball to reds; blues press to win it back and stop a mini goal.', 'Reds must complete 3 passes before scoring.', NULL, NULL, '11v11', 22, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('11v11 high press conditioned game', 'conditioned_game', 'opposed', 'out_of_possession', 147, 147, 'Session 7: Practice 4', NULL, 'Press high and aggressively throughout a full game and score straight after winning it.', 'Full pitch 11v11; blues in 3-5-2, reds in any formation (4-4-2, 4-2-3-1, 3-5-2, 3-4-3).', 'Always start from the red GK; reds build up through pressure to score; blues press high, win the ball and score immediately.', 'Reds: passes along the ground, 2 touches in their defensive half (unlimited in attacking half), 5 passes in their half before moving up. Restart from the GK after a goal or ball out.', NULL, 'Coach keeps players focused on aggressive pressing.', '11v11', 22, 22, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Back-three line movements v servers', 'defending', 'passive', 'out_of_possession', 149, 152, 'Session 8: Practice 1', NULL, 'Train the back three''s movement, anticipation and organisation for different ball situations.', '3 blue CBs and a DM; 5 red mannequins as reference; 3 red serving players in front. Wing backs can be added.', 'Servers circulate (max 2 touches) then play a forward ground pass in front of the mannequins; the nearest CB anticipates, steps out to win it and passes to the DM, who returns it to a server.', 'Servers max 2 touches.', 'Variation 2 aerial pass: nearest CB attacks the ball, the others shift across to cover. Variation 3 open ball: when a server dribbles forward the DM shifts and the 3 CBs drop together; when the ball goes back they push up. Variation 4 deep pass in behind: CBs retreat, one collects the long ball and finds the DM while the others cover and balance.', 'Anticipation; cover and balance; drop on open ball, push up on back pass.', '3 CBs + DM v 3 servers', 7, 9, NULL, NULL, NULL, NULL, false, false, false, NULL, 300),
  ('Defensive line SSG with counter to mini goals', 'defending', 'opposed', 'out_of_possession', 153, 154, 'Session 8: Practice 2', NULL, 'Organise the back line correctly against different tactical situations and counter after winning it.', 'Blues: 3 CBs, 2 wing backs, 1 DM + GK; reds: 4 midfielders and 2 forwards (4-4-2, any shape); 2 mini goals for the blues at the far end.', 'Coach passes; reds try to play in behind the blue line into the end zone and score, following set instructions (e.g. pass wide). Blues adjust to the ball (WB contests wide, others shift, far WB drops), win it and counter.', 'Blues have 8 seconds after winning it to score in either mini goal. Restart from the coach after a goal or ball out.', 'Coach changes tactical situations: a CB steps up to mark a No.10, 3v2 at the back against a 3-1-2, defend an open ball, defend a deep pass in behind.', NULL, '6 (+GK) v 6', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 310)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'coaching-3-5-2-tactics-125-tactical-solutions-and-practices') b;
INSERT INTO schema_migrations (filename) VALUES ('2257-exercises-book-coaching-3-5-2-tactics-125-tactical-solutions-and-practices.sql') ON CONFLICT DO NOTHING;
COMMIT;
